"""Summarize mailbox letters without modifying the node."""
import argparse
from datetime import datetime, timedelta
import json
import os
from pathlib import Path
import re


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = frozenset(("DONE", "BLOCKED", "NEEDS-USER", "FAILED"))


def children(path, directories=False):
    with os.scandir(path) as entries:
        return sorted(
            (entry for entry in entries
             if not entry.name.startswith(".")
             and (entry.is_dir(follow_symlinks=False) if directories
                  else entry.is_file(follow_symlinks=False))),
            key=lambda entry: entry.name,
        )


def directory(path):
    return os.path.isdir(path) and not os.path.islink(path)


def read_letter(path, now):
    lines = Path(path).read_text(encoding="utf-8", errors="replace").splitlines()
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status", "at")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    name = os.path.basename(path)
    if not NAME.match(name):
        return None, "bad_name"
    try:
        datetime.strptime(name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"],
            "to": fields["to"], "status": fields["status"],
            "at": at, "re": fields.get("re", "")}, None


def summarize(root, now):
    boxes = {}
    paths = []
    for mailbox in children(root, directories=True):
        inbox = os.path.join(mailbox.path, "inbox")
        if not directory(inbox):
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for where in ("inbox", "done"):
            location = inbox if where == "inbox" else os.path.join(inbox, "done")
            if where == "done" and not directory(location):
                continue
            for entry in children(location):
                if entry.name.endswith(".md"):
                    relative = "/".join((mailbox.name, "inbox") +
                                        (() if where == "inbox" else ("done",)) +
                                        (entry.name,))
                    paths.append((relative, entry.path, mailbox.name, where))
    letters = []
    bad = []
    seen = set()
    for relative, path, mailbox, where in sorted(paths):
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        letter["where"] = where
        letters.append(letter)
        if where == "done":
            boxes[mailbox]["done"] += 1
        else:
            counts = boxes[mailbox]["inbox"]
            status = letter["status"]
            counts[status] = counts.get(status, 0) + 1
    resolved = {letter["re"] for letter in letters
                if letter["re"] and letter["status"] in RESOLVING}
    opened = [{"id": letter["id"], "from": letter["from"],
               "to": letter["to"], "where": letter["where"],
               "age_min": (now - letter["at"]) // timedelta(minutes=1)}
              for letter in letters
              if letter["status"] == "REQUEST" and letter["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only node mailtodo summary")
    parser.add_argument("folder")
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not os.path.isdir(args.folder):
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
